cypress_script:
describe('Checkout Information Form', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
    cy.visit('https://www.saucedemo.com/checkout-step-one.html');
  });
  it('should navigate to the next page with valid inputs', () => {
    cy.get('[data-test="firstName"]').type('John');
    cy.get('[data-test="lastName"]').type('Doe');
    cy.get('[data-test="postalCode"]').type('12345');
    cy.get('[data-test="continue"]').click();
    cy.url().should('include', '/checkout-step-two.html');
  });
  it('should not navigate on empty form submission', () => {
    cy.get('[data-test="continue"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/checkout-step-one.html');
    cy.get('[data-test="secondary-header"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Checkout Information Form', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
    await page.goto('https://www.saucedemo.com/checkout-step-one.html');
  });
  test('should navigate to the next page with valid inputs', async ({ page }) => {
    await page.fill('[data-test="firstName"]', 'John');
    await page.fill('[data-test="lastName"]', 'Doe');
    await page.fill('[data-test="postalCode"]', '12345');
    await page.click('[data-test="continue"]');
    await expect(page).toHaveURL(/checkout-step-two.html/);
  });
  test('should not navigate on empty form submission', async ({ page }) => {
    await page.click('[data-test="continue"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/checkout-step-one.html');
    await expect(page.locator('[data-test="secondary-header"]').isVisible()).toBeTruthy();
  });
});
